import { randomUUID } from "crypto";
import { DomainError } from "../domain/DomainError";
import { ProjectRepository, TaskRepository, UserRepository } from "../domain/Repositories";
import { Task } from "../domain/Task";
import { CreateTaskInput, TaskDto, toTaskDto } from "./TaskDtos";

export class CreateTaskUseCase {
  public constructor(
    private readonly projects: ProjectRepository,
    private readonly users: UserRepository,
    private readonly tasks: TaskRepository,
  ) {}

  public execute(input: CreateTaskInput): TaskDto {
    if (!this.projects.findById(input.projectId)) {
      throw new DomainError("Project does not exist");
    }
    if (input.assigneeId && !this.users.findById(input.assigneeId)) {
      throw new DomainError("Assignee does not exist");
    }
    const dueDate = input.dueDate ? new Date(input.dueDate) : undefined;
    if (dueDate && Number.isNaN(dueDate.getTime())) {
      throw new DomainError("Due date must be a valid ISO date");
    }
    const task = new Task(randomUUID(), input.projectId, input.title, input.description, dueDate, input.assigneeId, input.status);
    this.tasks.save(task);
    return toTaskDto(task);
  }
}

